const modes = {
 only: {title:'introOnly',desc:'introOnlyDesc',note:'introOnlyNote',selection:'selectionOnly',branches:['c13_octoprint_cleanup'],dev:false},
 sd: {title:'introSd',desc:'introSdDesc',note:'introSdNote',selection:'selectionSd',branches:['c13_sd','c14_sd'],dev:false},
 host: {title:'introHost',desc:'introHostDesc',note:'introHostNote',selection:'selectionHost',branches:['c13_octoprint','c14_octoprint'],dev:false}
};
let lang='es',mode='sd';
const $=(s)=>document.querySelector(s);
const tr=(k)=>translations[lang][k]??translations.es[k]??k;
const esc=(s)=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const link=(href,label,style='')=>`<a class="action-link ${style}" href="${href}" target="_blank" rel="noopener noreferrer">${esc(label)} <span aria-hidden="true">↗</span></a>`;
const section=(id,n,title,lead,content,kind='common')=>`<section id="${id}" class="content-section"><div class="section-topline"><span class="section-number">${String(n).padStart(2,'0')}</span><span class="section-label">${esc(tr(kind==='common'?'commonLabel':kind==='only'?'onlyLabel':'hostLabel'))}</span></div><h2>${esc(tr(title))}</h2><p class="lead">${esc(tr(lead))}</p>${content}</section>`;
function screenshotCard(item){
 const t=menuCopy[lang];
 const local=`assets/screens/${item.id}.png`;
 const fallback=item.demo?`https://raw.githubusercontent.com/navaismo/Marlin_bugfix_2.1_E3V3SE/c13_sd/media/${item.demo}`:'';
 // Local screenshot is preferred. A verified source GIF is the fallback when available.
 return `<div class="menu-photo"><img class="menu-photo-img" src="${local}" data-fallback="${fallback}" alt="${esc(t.visual)}: ${esc(item.id)}" loading="lazy"><div class="menu-photo-empty" hidden><span aria-hidden="true">▧</span><strong>${esc(t.missing)}</strong><small>${esc(t.missingDesc)}</small></div><a class="menu-photo-open" href="${local}" target="_blank" rel="noopener noreferrer" hidden>${esc(t.openPhoto)} ↗</a></div>`;
}
function lcdPaths(item){return `<div class="menu-location"><span class="menu-location-title">⌖ ${esc(menuCopy[lang].menuPath)}</span>${item.paths.map(path=>`<div class="menu-breadcrumb">${path.map((bit,i)=>`<span>${esc(bit)}</span>${i<path.length-1?'<b aria-hidden="true">›</b>':''}`).join('')}</div>`).join('')}</div>`}
function menuRows(items,info,basics=false){return `<div class="menu-guide-list">${items.map((item,i)=>{const [emoji,title,desc,tip]=basics?info[i]:['',...info[i],''];return `<article class="menu-guide-card"><div class="menu-guide-copy"><div class="menu-guide-heading">${basics?`<span class="guide-emoji" aria-hidden="true">${emoji}</span>`:''}<div><h3>${esc(title)}</h3>${item.optional?`<span class="guide-optional">${esc(menuCopy[lang].optional)}</span>`:''}</div></div><p>${esc(desc)}</p>${lcdPaths(item)}${basics&&tip?`<div class="menu-guide-tip">↳ ${esc(tip)}</div>`:''}</div>${screenshotCard(item)}</article>`}).join('')}</div>`}
function wireMenuScreens(){
 $('#guide-content').querySelectorAll('.menu-photo-img').forEach(img=>{
  let fallbackUsed=false;
  const placeholder=()=>{img.hidden=true;img.nextElementSibling.hidden=false;img.parentElement.querySelector('.menu-photo-open').hidden=true};
  img.addEventListener('error',()=>{if(!fallbackUsed && img.dataset.fallback){fallbackUsed=true;img.src=img.dataset.fallback}else placeholder()});
  img.addEventListener('load',()=>{const a=img.parentElement.querySelector('.menu-photo-open');a.href=img.currentSrc||img.src;a.hidden=false;img.nextElementSibling.hidden=true;img.hidden=false});
  if(img.complete){if(img.naturalWidth){const a=img.parentElement.querySelector('.menu-photo-open');a.href=img.src;a.hidden=false}else if(img.src && !img.naturalWidth){if(img.dataset.fallback){fallbackUsed=true;img.src=img.dataset.fallback}else placeholder()}}
 });
}

function cards(data){return `<div class="cal-grid">${data.map(([emoji,title,desc,tip])=>`<article class="info-card"><div class="card-emoji" aria-hidden="true">${emoji}</div><h3>${esc(title)}</h3><p>${esc(desc)}</p><span class="tip">↳ ${esc(tip)}</span></article>`).join('')}</div>`}
function steps(data){return `<div class="steps">${data.map(([title,desc,emoji],i)=>`<div class="step"><span class="step-index">${i+1}</span><div class="step-body"><h3>${esc(title)}</h3><p>${esc(desc)}</p></div>${emoji?`<span class="step-art" aria-hidden="true">${emoji}</span>`:''}</div>`).join('')}</div>`}
function note(text,warn=false){return `<p class="${warn?'notice warn':'simple-note'}">${esc(text)}</p>`}
function mount(){
 document.documentElement.lang=lang;
 updateThemeButton();
 document.querySelectorAll('[data-i18n]').forEach(el=>{let k=el.dataset.i18n;if(k==='heroTitle')el.innerHTML=tr(k);else el.textContent=tr(k)});
 document.querySelectorAll('[data-lang]').forEach(el=>{let active=el.dataset.lang===lang;el.classList.toggle('active',active);el.setAttribute('aria-pressed',active?'true':'false')});
 document.querySelectorAll('[data-mode]').forEach(el=>{let active=el.dataset.mode===mode;el.setAttribute('aria-selected',active?'true':'false');el.tabIndex=active?0:-1});
 const m=modes[mode];$('#selection-hint').textContent=tr(m.selection);
 $('#guide').setAttribute('aria-labelledby',`tab-${mode}`);
 const intro=`<div class="mode-intro"><div class="mode-intro-top"><span class="version-eyebrow">${esc(tr('sectionIntro'))}</span><span class="status-pill ${m.dev?'warning':''}">${esc(tr(m.dev?'statusDev':'statusStable'))}</span></div><h2>${esc(tr(m.title))}</h2><p>${esc(tr(m.desc))}</p>${mode==='only'?`<div class="memory-spotlight"><span class="memory-spotlight-icon" aria-hidden="true">✦</span><div><strong>${esc(tr('onlyMemoryTitle'))}</strong><p>${esc(tr('onlyMemoryDesc'))}</p></div></div>`:''}<div class="branch-row"><span>${esc(tr('branchLabel'))}</span>${m.branches.map(b=>`<a href="${URLS.branches+b}" target="_blank" rel="noopener noreferrer">${b} ↗</a>`).join('')}</div><div class="notice ${m.dev?'warn':''}"><strong>ⓘ</strong> ${esc(tr(m.note))}</div></div>`;
 let n=0;let html=intro;let toc=[];
 const add=(id,title,lead,body,kind='common')=>{n++;toc.push([id,tr(title)]);html+=section(id,n,title,lead,body,kind)};
 add('installation','installTitle','installLead',steps(tr('installSteps'))+`<div class="linkbar">${link(URLS.releases,tr('releasesButton'),'primary')}${link(URLS.actions,tr('buildButton'))}${link(URLS.wiki,tr('wikiButton'))}</div>${note(tr('releaseCaution'),true)}${note(tr('installFoot'))}`);
 add('first-steps','basicsTitle','basicsLead',menuRows(screenGuides.basics,tr('basics'),true)+note(menuCopy[lang].photoNote)+note(tr('basicsFoot')));
 add('menus','extrasTitle','extrasLead',menuRows(screenGuides.extras,menuCopy[lang].extraRows)+note(tr('extrasFoot')));
 const thumbnailImage=mode==='only'?'assets/octoprint-thumbnail.jpg':'https://raw.githubusercontent.com/navaismo/Octoprint-LCD_E3V3SE/main/media/Prev.jpg';
 const thumbContent=`<div class="visual-split"><div class="visual-explainer"><h3>${esc(tr(mode==='sd'?'thumbSdTitle':'thumbHostTitle'))}</h3><p>${esc(tr(mode==='sd'?'thumbSdDesc':'thumbHostDesc'))}</p><div class="linkbar">${mode==='sd'?link(URLS.script,tr('thumbAction')):link(URLS.m73,tr('thumbM73'))}</div></div><div class="visual-preview"><img loading="lazy" src="${thumbnailImage}" alt="LCD E3V3SE thumbnail preview"/><div class="caption">${esc(tr('thumbPicture'))}</div></div></div>${note(tr('thumbFoot'))}`;
 add('thumbnails','thumbnailsTitle','thumbnailsLead',thumbContent);
 if(mode!=='sd'){
  const pluginAlert=mode==='only'?'pluginsOnlyAlert':'pluginsHostAlert';
  add('octoprint','pluginsTitle','pluginsLead',steps(tr('pluginsSteps'))+note(tr(pluginAlert),mode==='only')+`<div class="linkbar">${link(URLS.lcd,tr('pluginLink'),'primary')}${mode==='only'?link(URLS.lcdCleanup,tr('pluginCleanupLink')):link(URLS.lcdReleases,tr('pluginReleaseLink'))}</div><div class="visual-split"><div class="visual-preview light"><img loading="lazy" src="https://raw.githubusercontent.com/navaismo/Octoprint-LCD_E3V3SE/main/media/Settings.png" alt="OctoPrint LCD plugin settings"/></div><div class="visual-explainer"><h3>OctoPrint LCD E3V3SE</h3><p>${esc(tr('pluginsLead'))}</p></div></div>`,'host');
  add('input-shaping','shapingTitle','shapingLead',steps(tr('shapingSteps'))+note(tr('shapingFoot'))+`<div class="linkbar">${link(URLS.shaping,tr('shapingLink'),'primary')}${link(URLS.shapingReleases,tr('releasesButton'))}</div><div class="visual-split"><div class="visual-preview light"><img loading="lazy" src="https://raw.githubusercontent.com/navaismo/Octoprint-Pinput_Shaping/main/assets/ui-test-setup.png" alt="Pinput Shaping resonance test settings"/></div><div class="visual-explainer"><h3>Pinput Shaping</h3><p>${esc(tr('shapingLead'))}</p></div></div>`,'host');
 }
 if(mode==='only'){
  const skinCard=(kind,name,desc)=>`<article class="shot-card"><div class="concept-label">${esc(tr('skinConcept'))}</div><a class="skin-preview" href="assets/skin-${kind}-collage.jpg" aria-label="${esc(tr('skinOpen')+' '+name)}" data-skin-name="${esc(name)}"><img class="skin-image" loading="lazy" src="assets/skin-${kind}-collage.jpg" alt="${esc(tr('skinPhotoAlt')+' '+name)}"><span>${esc(tr('skinOpen'))} ↗</span></a><h3>${esc(name)}</h3><p>${esc(desc)}</p></article>`;
  add('skins','skinsTitle','skinsLead',`<div class="shot-grid">${skinCard('octoprint',tr('skinOctoTitle'),tr('skinOctoDesc'))}${skinCard('eva',tr('skinEvaTitle'),tr('skinEvaDesc'))}</div>${note(tr('skinFoot'))}${note(tr('skinTjc'),true)}<div class="linkbar">${link(URLS.eduard,tr('skinEduardLink'))}</div>`,'only');
 }
 html+=`<section id="cacomixtle" class="content-section pad-section" aria-labelledby="pad-title"><div class="pad-showcase"><div class="pad-copy"><span class="pad-kicker"><span aria-hidden="true">✳</span> ${esc(tr('padEyebrow'))}</span><div class="pad-app-name"><span class="pad-app-icon" aria-hidden="true">⌘</span> CacomixtlePad</div><h2 id="pad-title">${esc(tr('padHighlight'))}</h2><p class="pad-lead">${esc(tr('padDesc'))}</p><div class="pad-points"><span>✓ ${esc(tr('padFeatureOne'))}</span><span>✓ ${esc(tr('padFeatureTwo'))}</span><span>✓ ${esc(tr('padFeatureThree'))}</span></div><div class="pad-actions">${link(URLS.cacomixtle,tr('padButton'),'primary')}</div></div><div class="pad-preview"><div class="pad-preview-caption"><span class="live-dot" aria-hidden="true"></span> ${esc(tr('padDemoLabel'))}</div><div class="pad-device"><div class="pad-camera" aria-hidden="true"></div><div class="pad-display"><img class="pad-demo-gif" src="assets/cacomixtlepad-interfacee.gif" alt="${esc(tr('padDemoAlt'))}" hidden><div class="pad-demo-placeholder"><div class="pad-play" aria-hidden="true">▶</div><strong>CacomixtlePad</strong><p>${esc(tr('padDemoHint'))}</p><code>assets/cacomixtlepad-interfacee.gif</code></div></div></div></div></div></section>`;
 toc.push(['cacomixtle','CacomixtlePad']);
 $('#guide-content').innerHTML=html;
 $('#toc-links').innerHTML=toc.map(([id,title])=>`<a href="#${id}">${esc(title)}</a>`).join('');
 wireMenuScreens();
 wirePadGif();
}
const skinDialog=$('#skin-dialog');
$('#guide-content').addEventListener('click',event=>{
 const preview=event.target.closest('.skin-preview');
 if(!preview || typeof skinDialog.showModal!=='function')return;
 event.preventDefault();
 $('#skin-dialog-title').textContent=preview.dataset.skinName;
 $('#skin-dialog-image').src=preview.href;
 $('#skin-dialog-image').alt=preview.querySelector('img').alt;
 $('#skin-dialog-original').href=preview.href;
 skinDialog.showModal();
});
$('#skin-dialog-close').addEventListener('click',()=>skinDialog.close());
function wirePadGif(){
 const img=$('#guide-content .pad-demo-gif');
 if(!img)return;
 const empty=img.parentElement.querySelector('.pad-demo-placeholder');
 img.addEventListener('load',()=>{img.hidden=false;empty.hidden=true});
 img.addEventListener('error',()=>{img.hidden=true;empty.hidden=false});
 if(img.complete&&img.naturalWidth){img.hidden=false;empty.hidden=true}
}
function switchMode(value,focus=false){if(!modes[value])return;mode=value;mount();try{let u=new URL(location.href);u.searchParams.set('mode',mode);history.replaceState(null,'',u.pathname+u.search+u.hash)}catch{}if(focus)$('#guide').focus({preventScroll:true})}
function switchLanguage(value){if(!translations[value])return;lang=value;try{localStorage.setItem('guide_lang',lang)}catch{}mount()}
const themeLabels={
 es:{light:'Cambiar al tema claro',dark:'Cambiar al tema oscuro'},
 en:{light:'Switch to light theme',dark:'Switch to dark theme'},
 ru:{light:'Включить светлую тему',dark:'Включить тёмную тему'}
};
const themeButton=$('#theme-toggle');
const darkTheme=$('#dark-theme');
let theme='dark';
function updateThemeButton(){
 const next=theme==='dark'?'light':'dark';
 const label=themeLabels[lang][next];
 themeButton.setAttribute('aria-label',label);
 themeButton.title=label;
 themeButton.firstElementChild.textContent=next==='light'?'☀':'☾';
}
function setTheme(value){
 theme=value;
 darkTheme.disabled=theme==='light';
 document.documentElement.dataset.theme=theme;
 document.querySelector('meta[name="theme-color"]').content=theme==='dark'?'#081321':'#ffffff';
 updateThemeButton();
}
themeButton.addEventListener('click',()=>{
 setTheme(theme==='dark'?'light':'dark');
 try{localStorage.setItem('guide_theme',theme)}catch(error){console.warn('Unable to save theme preference:',error)}
});
document.querySelectorAll('[data-lang]').forEach(b=>b.addEventListener('click',()=>switchLanguage(b.dataset.lang)));
document.querySelectorAll('[data-mode]').forEach(b=>b.addEventListener('click',()=>switchMode(b.dataset.mode,false)));
const tabs=Array.from(document.querySelectorAll('[data-mode]'));
tabs.forEach((tab,i)=>tab.addEventListener('keydown',event=>{let offset=event.key==='ArrowRight'?1:event.key==='ArrowLeft'?-1:0;if(!offset)return;event.preventDefault();let next=tabs[(i+offset+tabs.length)%tabs.length];switchMode(next.dataset.mode);next.focus()}));
try{const saved=localStorage.getItem('guide_lang');if(translations[saved])lang=saved;else if(navigator.language?.toLowerCase().startsWith('ru'))lang='ru';else if(navigator.language?.toLowerCase().startsWith('en'))lang='en'}catch{}
try{const saved=localStorage.getItem('guide_theme');if(saved==='light'||saved==='dark')theme=saved}catch(error){console.warn('Unable to read theme preference:',error)}
setTheme(theme);
const selected=new URLSearchParams(location.search).get('mode');if(modes[selected])mode=selected;
mount();
